// Get the RESCHEDULED appointment
const appointments = $('Collect Appointments').all();

const rescheduledAppointment = appointments.find(
    item =>
        String(item.json.status ?? '')
            .trim()
            .toUpperCase() === 'RESCHEDULED'
);

if (!rescheduledAppointment) {
    throw new Error('No RESCHEDULED appointment found.');
}

const appointmentData = rescheduledAppointment.json;

const appointmentId = appointmentData.clinic_id;
const patientId = appointmentData.patient_id;
const doctorId = appointmentData.doctor_id;
const purpose = appointmentData.purpose;

// Get all Google Calendar events
const events = $input.all();

// Find the old calendar event
const matchingEvent = events.find(item => {

    const event = item.json;

    const description = String(
        event.description ?? ''
    );

    const summary = String(
        event.summary ?? ''
    );

    // Method 1:
    // Match by Appointment ID if it exists
    if (description.includes(appointmentId)) {
        return true;
    }

    // Method 2:
    // Match old event using Patient ID + Doctor ID
    const patientMatch =
        description.includes(`Patient: ${patientId}`);

    const doctorMatch =
        description.includes(`Doctor: ${doctorId}`);

    const purposeMatch =
        summary.toLowerCase() ===
        String(purpose).toLowerCase();

    return patientMatch &&
           doctorMatch &&
           purposeMatch;
});

if (!matchingEvent) {

    throw new Error(
        `No calendar event found for appointment ${appointmentId}. ` +
        `Patient: ${patientId}, Doctor: ${doctorId}`
    );
}

// Return the OLD Google Calendar event ID
// together with the NEW appointment information
return [
    {
        json: {

            // OLD GOOGLE CALENDAR EVENT
            eventId: matchingEvent.json.id,

            // NEW APPOINTMENT DATA
            appointmentId: appointmentId,

            patient_id: appointmentData.patient_id,
            patient_name: appointmentData.patient_name,
            patient_email: appointmentData.patient_email,

            doctor_id: appointmentData.doctor_id,
            doctor_name: appointmentData.doctor_name,
            specialization: appointmentData.specialization,

            date: appointmentData.date,
            time: appointmentData.time,
            purpose: appointmentData.purpose,
            status: appointmentData.status,

            start_iso: appointmentData.start_iso,
            end_iso: appointmentData.end_iso
        }
    }
];
